    "Только читает чат, без входа в аккаунт. Нужен для ленты, счётчиков, голосований и сценариев. Подключай в одном пульте, иначе всё посчитается дважды.": "Only reads the chat, no account login. Needed for the feed, counters, polls and scenarios. Connect it in one panel only, otherwise everything is counted twice.",
    "Чат привязан к комнате: у каждой комнаты свой канал и своя лента. При смене комнаты чат переключается сам.": "Chat belongs to the room: every room has its own channel and its own feed. The chat switches by itself when you change the room.",
