    "Ключи лежат в этом браузере открытым текстом. Если на этот компьютер попадёт вирус или вредный скрипт, он сможет забрать твои комнаты и управлять оверлеем стримера. Поставь пароль: тогда ключи хранятся зашифрованными.": "The keys are stored in this browser as plain text. If malware or a malicious script gets onto this computer, it can take your rooms and control the streamer's overlay. Set a password: then the keys are stored encrypted.",
