    "отпечаток не совпал: код устарел": "fingerprint mismatch: the code is outdated",
    "Сертификат сервера стримера не совпал с отпечатком из твоего кода. Попроси стримера прислать новый код и вставь его на экране сессий.": "The streamer's server certificate does not match the fingerprint in your code. Ask the streamer for a new code and paste it on the sessions screen.",
    "сервер не отвечает": "server not responding",
    "Hudini Host не отвечает ни по одному адресу из кода. Проверь, что у тебя и у стримера включён один и тот же VPN (Tailscale, Radmin, Porthole), а программа запущена.": "Hudini Host does not answer at any address from the code. Check that you and the streamer are on the same VPN (Tailscale, Radmin, Porthole) and that the app is running.",
