    "Эта комната уже есть в пульте, но с другими ключами.\nПульт открыт с твоими прежними ключами. Если стример их сменил, попроси новую ссылку-приглашение.": "This room is already in the panel, but with different keys.\nThe panel opened with your old keys. If the streamer changed them, ask for a new invitation link.",
