    "Нажми, чтобы узнать, как её запустить. Пока программы нет, можно готовить экран: всё уйдёт при подключении.": "Click to see how to start it. Until then you can prepare the screen: everything is sent once it connects.",
    "Ссылка для Hudini Host:": "Link for Hudini Host:",
    "Стример вставляет её в программу Hudini Host, а программа даёт ссылку для OBS": "The streamer pastes it into Hudini Host, and the app gives the link for OBS",
    "Ссылка скопирована: стример вставляет её в программу Hudini Host": "Link copied: the streamer pastes it into Hudini Host",
    "Новая комната: скопируй ссылку и отдай стримеру для Hudini Host": "New room: copy the link and give it to the streamer for Hudini Host",
    "Ключи сменены: отдай стримеру новую ссылку для Hudini Host": "Keys changed: give the streamer the new link for Hudini Host",
    "Если ссылка утекла или надо закрыть доступ модератору": "If the link leaked or you need to revoke a moderator's access",
    "Старая ссылка и все приглашения перестанут работать, а Hudini Host отключит всех модераторов со старыми ключами.": "The old link and all invites stop working, and Hudini Host disconnects every moderator with the old keys.",
    "Стример вставляет новую ссылку в программу, другим модераторам нужны новые приглашения.": "The streamer pastes the new link into the app; other moderators need new invites.",
    "Делай так, если ссылка утекла или надо закрыть доступ человеку.": "Do this if the link leaked or you need to revoke someone's access.",
    "Экран стримера меняется через программу Hudini Host": "The streamer's screen changes through the Hudini Host app",
    "Стример скачивает и запускает": "The streamer downloads and runs",
    "у себя на ПК.": "on their PC.",
    "Ты жмёшь «📋 Копировать» вверху и отправляешь ссылку стримеру, он вставляет её в программу.": "You press “📋 Copy” at the top and send the link to the streamer, who pastes it into the app.",
    "В OBS стример ставит ссылку из программы (http://localhost:7777/…). Пульт подключится сам.": "In OBS the streamer uses the link from the app (http://localhost:7777/…). The panel connects by itself.",
    "Пока программы нет, можно готовить экран: всё уйдёт стримеру при подключении.": "Until the app is running you can prepare the screen: everything goes to the streamer once it connects.",
    "Программа стримера ничего не удаляет сама. Убери ненужные файлы или попроси стримера увеличить лимиты на странице Hudini Host.": "The streamer's app never deletes anything by itself. Remove files you don't need or ask the streamer to raise the limits on the Hudini Host page.",
