    "👋 Привет! Это Hudini": "👋 Hi! This is Hudini",
    "Отсюда ты показываешь на экране стримера текст, картинки, таймеры и эффекты. Покажу главное за минуту.": "From here you show text, pictures, timers and effects on the streamer's screen. Let me show you the basics in a minute.",
    "Добавляй здесь": "Add things here",
    "Текст, картинки, GIF, видео, таймеры и счётчики. Картинку можно просто перетащить на холст или вставить через Ctrl+V.": "Text, pictures, GIFs, videos, timers and counters. You can simply drop a picture onto the canvas or paste it with Ctrl+V.",
    "Это экран стримера": "This is the streamer's screen",
    "Отсюда ты показываешь на своём стриме текст, картинки, таймеры и эффекты. Покажу главное за минуту.": "From here you show text, pictures, timers and effects on your own stream. Let me show you the basics in a minute.",
    "Это экран твоего стрима": "This is your stream's screen",
    "Здесь видно связь пульта с Hudini Host на этом компьютере и работает ли виджет в OBS. Если что-то не так, нажми на плашку.": "Here you see the panel's connection to Hudini Host on this computer and whether the widget works in OBS. If something is wrong, click the badge.",
    "Рамка, пароль, очистка": "Frame, password, clear",
    "Всё, что здесь, видно на стриме. Тащи элемент мышкой, меняй размер за уголок, крути за кружок. Ctrl+Z отменяет.": "Everything here is visible on stream. Drag an element with the mouse, resize it by the corner, rotate it by the circle. Ctrl+Z undoes.",
    "Кликни по элементу, и здесь появятся цвет, шрифт и анимации. Глазик 👁 прячет элемент со стрима, не удаляя его.": "Click an element and its color, font and animations appear here. The eye 👁 hides it from the stream without deleting it.",
    "Связь со стримером": "Connecting to the streamer",
    "В меню «Ещё» нажми «Копировать» и отправь ссылку стримеру. Он вставляет её в программу Hudini Host на своём ПК, и пульт находит его сам.": "In the “More” menu press “Copy” and send the link to the streamer. They paste it into Hudini Host on their PC, and the panel finds it by itself.",
    "Всё ли на связи": "Is everything connected",
    "Полоски и миллисекунды: связь с программой стримера и её задержка. Рядом видно, работает ли виджет в OBS. Если что-то не так, нажми на плашку.": "The bars and milliseconds show the link to the streamer's app and its delay. Next to it you see whether the widget in OBS works. If something is off, click the badge.",
    "⋯ Ещё": "⋯ More",
    "Ссылка для стримера, рамка, пароль, очистка": "Streamer link, frame, password, clear",
    "Метки β и α": "β and α marks",
    "β: работает, но ещё обкатывается. α: эксперимент. Нажми на метку, чтобы узнать больше или сообщить о проблеме.": "β: works but is still being tested. α: an experiment. Click a mark to learn more or report a problem.",
    "Гайд всегда здесь": "The guide is always here",
    "Кнопка ❓ покажет обучение ещё раз и откроет справку прямо в пульте.": "The ❓ button replays the tour and opens the help right in the panel.",
    "🎛 Настроим под тебя": "🎛 Let's set it up for you",
    "Выбери, как пульт будет выглядеть. Всё это можно поменять потом: Комната → Вид пульта.": "Choose how the panel should look. You can change all of it later: Room → Panel look.",
