    "или просто перетащи файл сюда": "or just drop a file here",
    "📁 Место для файлов модераторов": "📁 Space for moderators' files",
    "Модераторы загружают картинки, GIF и видео. Они хранятся на этом компьютере в папке программы, зашифрованными. Сколько места им дать?": "Moderators upload pictures, GIFs and videos. They're stored encrypted on this computer in the app's folder. How much space should they get?",
    "Один файл до, МБ": "One file up to, MB",
