    "Свой адрес для модераторов.": "Own address for moderators.",
    "Вместо бесплатного туннеля Cloudflare: Tailscale Funnel, свой туннель Cloudflare или свой домен. Направь его на": "Instead of the free Cloudflare tunnel: Tailscale Funnel, your own Cloudflare tunnel or your own domain. Point it at",
    "и впиши адрес вида": "and enter an address like",
    ". Пусто = обычный туннель.": ". Empty = the usual tunnel.",
    "Свой адрес сохранён ✓": "Own address saved ✓",
    "Вернул обычный туннель ✓": "Back to the usual tunnel ✓",
    "Адрес и пароль для пульта.": "Address and password for the panel.",
    "Обычно пульт находит программу сам. Если нет, модератор вписывает их в пульте: «Комната» → «Для продвинутых». Никому больше не показывай.": "Usually the panel finds the app by itself. If not, the moderator enters them in the panel: “Room” → “Advanced”. Don't show them to anyone else.",
    "адрес появится, когда заработает туннель": "the address appears once the tunnel works",
    "Новый пароль модераторов.": "New moderator password.",
    "Все модераторы отключатся на пару секунд и подключатся снова сами. Чтобы закрыть доступ человеку насовсем, модератор нажимает в пульте «♻ Сменить ключи», а ты вставляешь новую ссылку в шаг 1.": "All moderators disconnect for a couple of seconds and reconnect by themselves. To revoke someone's access for good, a moderator presses “♻ Change keys” in the panel and you paste the new link into step 1.",
    "🔑 Новый пароль": "🔑 New password",
