    "Здесь видно связь пульта с Hudini Host на этом компьютере и работает ли виджет в OBS. Если что-то не так, нажми на плашку.": "Тут видно зв'язок пульта з Hudini Host на цьому комп'ютері й чи працює віджет в OBS. Якщо щось не так, натисни на плашку.",
    "Рамка, пароль, очистка": "Рамка, пароль, очищення",
    "Всё, что здесь, видно на стриме. Тащи элемент мышкой, меняй размер за уголок, крути за кружок. Ctrl+Z отменяет.": "Усе, що тут, видно на стрімі. Тягни елемент мишкою, змінюй розмір за куточок, крути за кружечок. Ctrl+Z скасовує.",
    "Кликни по элементу, и здесь появятся цвет, шрифт и анимации. Глазик 👁 прячет элемент со стрима, не удаляя его.": "Клікни по елементу, і тут з'являться колір, шрифт і анімації. Око 👁 ховає елемент зі стріму, не видаляючи його.",
    "Связь со стримером": "Зв'язок зі стрімером",
    "В меню «Ещё» нажми «Копировать» и отправь ссылку стримеру. Он вставляет её в программу Hudini Host на своём ПК, и пульт находит его сам.": "У меню «Ще» натисни «Копіювати» й надішли посилання стрімеру. Він вставляє його в Hudini Host на своєму ПК, і пульт знаходить його сам.",
    "Всё ли на связи": "Чи все на зв'язку",
    "Полоски и миллисекунды: связь с программой стримера и её задержка. Рядом видно, работает ли виджет в OBS. Если что-то не так, нажми на плашку.": "Смужки й мілісекунди: зв'язок із програмою стрімера та її затримка. Поруч видно, чи працює віджет в OBS. Якщо щось не так, натисни на плашку.",
    "⋯ Ещё": "⋯ Ще",
    "Ссылка для стримера, рамка, пароль, очистка": "Посилання для стрімера, рамка, пароль, очищення",
    "Метки β и α": "Позначки β і α",
    "β: работает, но ещё обкатывается. α: эксперимент. Нажми на метку, чтобы узнать больше или сообщить о проблеме.": "β: працює, але ще обкатується. α: експеримент. Натисни на позначку, щоб дізнатися більше чи повідомити про проблему.",
    "Гайд всегда здесь": "Гайд завжди тут",
    "Кнопка ❓ покажет обучение ещё раз и откроет справку прямо в пульте.": "Кнопка ❓ покаже навчання ще раз і відкриє довідку прямо в пульті.",
    "🎛 Настроим под тебя": "🎛 Налаштуємо під тебе",
    "Выбери, как пульт будет выглядеть. Всё это можно поменять потом: Комната → Вид пульта.": "Вибери, як виглядатиме пульт. Усе це можна змінити потім: Кімната → Вигляд пульта.",
