    "Модераторы загружают картинки, GIF и видео. Они хранятся на этом компьютере в папке программы, зашифрованными. Сколько места им дать?": "Модератори завантажують картинки, GIF і відео. Вони зберігаються на цьому комп'ютері в папці програми, зашифрованими. Скільки місця їм дати?",
    "Один файл до, МБ": "Один файл до, МБ",
