    "Вместо бесплатного туннеля Cloudflare: Tailscale Funnel, свой туннель Cloudflare или свой домен. Направь его на": "Замість безкоштовного тунелю Cloudflare: Tailscale Funnel, свій тунель Cloudflare або свій домен. Спрямуй його на",
    "и впиши адрес вида": "і впиши адресу виду",
    ". Пусто = обычный туннель.": ". Порожньо = звичайний тунель.",
