    "Адрес и пароль для пульта.": "Адреса й пароль для пульта.",
    "Обычно пульт находит программу сам. Если нет, модератор вписывает их в пульте: «Комната» → «Для продвинутых». Никому больше не показывай.": "Зазвичай пульт знаходить програму сам. Якщо ні, модератор вписує їх у пульті: «Кімната» → «Для досвідчених». Більше нікому не показуй.",
    "адрес появится, когда заработает туннель": "адреса з'явиться, коли запрацює тунель",
    "Новый пароль модераторов.": "Новий пароль модераторів.",
    "Все модераторы отключатся на пару секунд и подключатся снова сами. Чтобы закрыть доступ человеку насовсем, модератор нажимает в пульте «♻ Сменить ключи», а ты вставляешь новую ссылку в шаг 1.": "Усі модератори відключаться на пару секунд і підключаться знову самі. Щоб закрити доступ людині назавжди, модератор тисне в пульті «♻ Змінити ключі», а ти вставляєш нове посилання в крок 1.",
    "🔑 Новый пароль": "🔑 Новий пароль",
    "Новый пароль ✓": "Новий пароль ✓",
    "Сменить пароль модераторов? Все модераторы отключатся на минуту.": "Змінити пароль модераторів? Усі модератори ненадовго відключаться.",
    "Файлы": "Файли",
    "Поиск адреса (общий сервер)": "Пошук адреси (спільний сервер)",
    "нет связи (пульт попробует последний адрес)": "немає зв'язку (пульт спробує останню адресу)",
    "Попроси модератора нажать в пульте «📋 Копировать» и вставь эту ссылку сюда. Нужно сделать один раз, программа её запомнит.": "Попроси модератора натиснути в пульті «📋 Копіювати» й встав це посилання сюди. Треба зробити один раз, програма його запам'ятає.",
