    "Теперь все команды на экран подписываются твоим ключом, а чужие отбрасываются. Старые ссылки для OBS больше не работают: нажми «📋 Копировать» и отправь стримеру НОВУЮ ссылку.": "Alle Befehle an den Bildschirm werden jetzt mit deinem Schlüssel signiert, fremde werden verworfen. Alte OBS-Links funktionieren nicht mehr: Drück «📋 Kopieren» und schick dem Streamer den NEUEN Link.",
