    "только модеры": "nur Mods",
    "Только читает чат, без входа в аккаунт. Нужен для ленты, счётчиков, голосований и сценариев. Подключай в одном пульте, иначе всё посчитается дважды.": "Liest nur den Chat, ohne Login. Nötig für Feed, Zähler, Umfragen und Szenarien. Nur in einem Pult verbinden, sonst wird alles doppelt gezählt.",
    "Чат привязан к комнате: у каждой комнаты свой канал и своя лента. При смене комнаты чат переключается сам.": "Der Chat gehört zum Raum: Jeder Raum hat seinen eigenen Kanal und seinen eigenen Verlauf. Beim Raumwechsel wechselt der Chat von selbst.",
    "торможение": "Abbremsen",
    "Тряска": "Wackeln",
    "Туннель для модераторов": "Tunnel für Mods",
    "туннель упал (код": "Tunnel abgestürzt (Code",
    "У каждого стримера своя комната, ключи и ссылка. Команды на экран подписываются ключом из этого пульта. «Бэкап» сохраняет всё (комнаты, сцены, библиотеку, анимации, сценарии) в файл под паролем.": "Jeder Streamer hat seinen eigenen Raum, Schlüssel und Link. Befehle an den Bildschirm werden mit dem Schlüssel aus diesem Pult signiert. «Backup» speichert alles (Räume, Szenen, Bibliothek, Animationen, Szenarien) in eine passwortgeschützte Datei.",
    "У стримера на 10 секунд появилась рамка по краям оверлея": "Beim Streamer erscheint 10 Sekunden lang ein Rahmen an den Overlay-Rändern",
    "У стримера старая версия виджета: свойства источника → «Обновить кэш текущей страницы».": "Der Streamer hat eine alte Widget-Version: Quelleneigenschaften → «Cache der aktuellen Seite aktualisieren».",
