    "⚠ Ключи комнат не защищены паролем": "⚠ Raumschlüssel sind nicht mit einem Passwort geschützt",
    "Ключи лежат в этом браузере открытым текстом. Если на этот компьютер попадёт вирус или вредный скрипт, он сможет забрать твои комнаты и управлять оверлеем стримера. Поставь пароль: тогда ключи хранятся зашифрованными.": "Die Schlüssel liegen unverschlüsselt in diesem Browser. Gelangt Schadsoftware oder ein bösartiges Skript auf diesen Computer, kann es deine Räume übernehmen und das Overlay des Streamers steuern. Setz ein Passwort: dann werden die Schlüssel verschlüsselt gespeichert.",
