    "⏳ Ждём Hudini Host": "⏳ Warte auf Hudini Host",
    "отпечаток не совпал: код устарел": "Fingerabdruck stimmt nicht: Code veraltet",
    "Сертификат сервера стримера не совпал с отпечатком из твоего кода. Попроси стримера прислать новый код и вставь его на экране сессий.": "Das Zertifikat des Streamer-Servers passt nicht zum Fingerabdruck in deinem Code. Bitte den Streamer um einen neuen Code und füge ihn auf dem Sitzungsbildschirm ein.",
    "сервер не отвечает": "Server antwortet nicht",
    "Hudini Host не отвечает ни по одному адресу из кода. Проверь, что у тебя и у стримера включён один и тот же VPN (Tailscale, Radmin, Porthole), а программа запущена.": "Hudini Host antwortet unter keiner Adresse aus dem Code. Prüfe, ob du und der Streamer im selben VPN seid (Tailscale, Radmin, Porthole) und das Programm läuft.",
    "подключаюсь к адресам из кода…": "verbinde mit den Adressen aus dem Code…",
    "Пробую адреса из кода стримера: ": "Probiere die Adressen aus dem Code des Streamers: ",
