    "Этого стримера нет в списке сессий.": "Dieser Streamer ist nicht in der Sitzungsliste.",
    "В коде стримера нет ключей комнаты. Попроси стримера прислать код из программы Hudini Host ещё раз.": "Der Code des Streamers enthält keine Raumschlüssel. Bitte den Streamer, den Code aus Hudini Host erneut zu senden.",
    "Эта комната уже есть в пульте, но с другими ключами.\nПульт открыт с твоими прежними ключами. Если стример их сменил, попроси новую ссылку-приглашение.": "Dieser Raum ist schon im Pult, aber mit anderen Schlüsseln.\nDas Pult wurde mit deinen alten Schlüsseln geöffnet. Hat der Streamer sie geändert, bitte um einen neuen Einladungslink.",
    "🆕 Обновить Hudini": "🆕 Hudini aktualisieren",
    "📂 Папка с данными": "📂 Datenordner",
    "Открыть папку, где пульт хранит ключи комнат, сцены и настройки. Файл store.json в ней — копия всего": "Öffnet den Ordner, in dem das Pult Raumschlüssel, Szenen und Einstellungen speichert. Die Datei store.json darin ist eine Kopie von allem",
