    "Ключи сменены: отдай стримеру новую ссылку для Hudini Host": "Schlüssel geändert: Gib dem Streamer den neuen Link für Hudini Host",
    "Если ссылка утекла или надо закрыть доступ модератору": "Wenn der Link geleakt ist oder du einem Mod den Zugang entziehen willst",
    "Старая ссылка и все приглашения перестанут работать, а Hudini Host отключит всех модераторов со старыми ключами.": "Der alte Link und alle Einladungen funktionieren nicht mehr, und Hudini Host trennt alle Mods mit den alten Schlüsseln.",
    "Стример вставляет новую ссылку в программу, другим модераторам нужны новые приглашения.": "Der Streamer fügt den neuen Link ins Programm ein, andere Mods brauchen neue Einladungen.",
    "Делай так, если ссылка утекла или надо закрыть доступ человеку.": "Mach das, wenn der Link geleakt ist oder du jemandem den Zugang entziehen willst.",
    "Экран стримера меняется через программу Hudini Host": "Der Bildschirm des Streamers ändert sich über das Programm Hudini Host",
    "Стример скачивает и запускает": "Der Streamer lädt herunter und startet",
    "у себя на ПК.": "auf seinem PC.",
    "Ты жмёшь «📋 Копировать» вверху и отправляешь ссылку стримеру, он вставляет её в программу.": "Du klickst oben auf „📋 Kopieren“ und schickst den Link dem Streamer, der ihn ins Programm einfügt.",
    "В OBS стример ставит ссылку из программы (http://localhost:7777/…). Пульт подключится сам.": "In OBS nutzt der Streamer den Link aus dem Programm (http://localhost:7777/…). Das Pult verbindet sich selbst.",
    "Пока программы нет, можно готовить экран: всё уйдёт стримеру при подключении.": "Bis das Programm läuft, kannst du den Bildschirm vorbereiten: Alles geht beim Verbinden an den Streamer.",
    "Программа стримера ничего не удаляет сама. Убери ненужные файлы или попроси стримера увеличить лимиты на странице Hudini Host.": "Das Programm des Streamers löscht nie selbst etwas. Entferne unnötige Dateien oder bitte den Streamer, die Limits auf der Seite von Hudini Host zu erhöhen.",
    "🧹 Удалить неиспользуемые файлы": "🧹 Unbenutzte Dateien löschen",
    "Удалить неиспользуемые файлы": "Unbenutzte Dateien löschen",
