    "Файлы хранятся у стримера в программе Hudini Host.": "Dateien liegen beim Streamer in Hudini Host.",
    "Один файл до": "Eine Datei bis",
    "Лимиты меняет стример на странице программы.": "Die Limits ändert der Streamer auf der Seite des Programms.",
    "Файлы хранятся у стримера в программе Hudini Host, а она сейчас не подключена": "Dateien liegen beim Streamer in Hudini Host, und das ist gerade nicht verbunden",
    "Файлы хранятся в программе Hudini Host, а она сейчас не подключена": "Dateien liegen in Hudini Host, und das ist gerade nicht verbunden",
    "а стример разрешил файлы до": "aber der Streamer erlaubt Dateien bis",
    "Для больших видео лучше ссылка или YouTube.": "Für große Videos nimm lieber einen Link oder YouTube.",
    "не загрузился": "wurde nicht hochgeladen",
    "файл больше, чем разрешил стример": "die Datei ist größer, als der Streamer erlaubt",
    "файлов уже столько, сколько разрешил стример": "es gibt schon so viele Dateien, wie der Streamer erlaubt",
    "место для файлов кончилось": "der Platz für Dateien ist voll",
    "Не получилось узнать список файлов": "Dateiliste konnte nicht geladen werden",
    "Все файлы используются: на экране, в сценах, библиотеке или сценариях": "Alle Dateien werden benutzt: auf dem Bildschirm, in Szenen, der Bibliothek oder Szenarien",
    "Их нет ни на экране, ни в сценах, библиотеке и сценариях этого пульта.": "Sie sind weder auf dem Bildschirm noch in Szenen, Bibliothek oder Szenarien dieses Pults.",
    "Если у другого модератора свои сцены с этими файлами, у него они пропадут.": "Wenn ein anderer Mod eigene Szenen mit diesen Dateien hat, verschwinden sie bei ihm.",
    "Их нет на экране и в сценах, библиотеке и сценариях модераторов.": "Sie sind weder auf dem Bildschirm noch in Szenen, Bibliotheken oder Szenarien der Mods.",
    "Файлы, нужные только модераторам, которые не подключались после обновления, могут удалиться.": "Dateien, die nur Mods brauchen, die seit dem Update nicht verbunden waren, können gelöscht werden.",
    "🧹 Удалено файлов": "🧹 Dateien gelöscht",
    "Не удалилось": "Nicht gelöscht",
    "Файлы у стримера": "Dateien beim Streamer",
    "Удалить из Hudini Host файлы, которых нет на экране, в сценах, библиотеке и сценариях": "Dateien aus Hudini Host löschen, die nicht auf dem Bildschirm, in Szenen, der Bibliothek oder Szenarien sind",
    "Файл не скопировался": "Datei wurde nicht kopiert",
    "файл лежит у другого стримера: добавь его заново": "die Datei liegt bei einem anderen Streamer: füge sie neu hinzu",
    "⚙ Для продвинутых: свой адрес Hudini Host": "⚙ Für Fortgeschrittene: eigene Hudini-Host-Adresse",
    "Обычно пульт находит программу стримера сам. Свой адрес нужен, если стример поднял Tailscale Funnel или свой туннель. Адрес и пароль модераторов есть на странице программы в разделе «Для продвинутых».": "Normalerweise findet das Pult das Programm des Streamers selbst. Eine eigene Adresse braucht man, wenn der Streamer Tailscale Funnel oder einen eigenen Tunnel eingerichtet hat. Adresse und Mod-Passwort stehen auf der Seite des Programms unter „Für Fortgeschrittene“.",
