    "👋 Привет! Это Hudini": "👋 Hallo! Das ist Hudini",
    "Отсюда ты показываешь на экране стримера текст, картинки, таймеры и эффекты. Покажу главное за минуту.": "Von hier aus zeigst du Text, Bilder, Timer und Effekte auf dem Bildschirm des Streamers. Ich zeig dir das Wichtigste in einer Minute.",
    "Добавляй здесь": "Hier hinzufügen",
    "Текст, картинки, GIF, видео, таймеры и счётчики. Картинку можно просто перетащить на холст или вставить через Ctrl+V.": "Text, Bilder, GIFs, Videos, Timer und Zähler. Ein Bild kannst du einfach auf die Leinwand ziehen oder mit Strg+V einfügen.",
    "Это экран стримера": "Das ist der Bildschirm des Streamers",
    "Отсюда ты показываешь на своём стриме текст, картинки, таймеры и эффекты. Покажу главное за минуту.": "Von hier aus zeigst du Text, Bilder, Timer und Effekte in deinem eigenen Stream. Ich zeig dir das Wichtigste in einer Minute.",
    "Это экран твоего стрима": "Das ist der Bildschirm deines Streams",
    "Здесь видно связь пульта с Hudini Host на этом компьютере и работает ли виджет в OBS. Если что-то не так, нажми на плашку.": "Hier siehst du die Verbindung des Panels zu Hudini Host auf diesem Computer und ob das Widget in OBS läuft. Wenn etwas nicht stimmt, klick auf das Feld.",
    "Рамка, пароль, очистка": "Rahmen, Passwort, Leeren",
    "Всё, что здесь, видно на стриме. Тащи элемент мышкой, меняй размер за уголок, крути за кружок. Ctrl+Z отменяет.": "Alles hier ist im Stream zu sehen. Zieh ein Element mit der Maus, ändere die Größe an der Ecke, dreh es am Kreis. Strg+Z macht rückgängig.",
    "Кликни по элементу, и здесь появятся цвет, шрифт и анимации. Глазик 👁 прячет элемент со стрима, не удаляя его.": "Klick auf ein Element, dann erscheinen hier Farbe, Schrift und Animationen. Das Auge 👁 versteckt es im Stream, ohne es zu löschen.",
    "Связь со стримером": "Verbindung zum Streamer",
    "В меню «Ещё» нажми «Копировать» и отправь ссылку стримеру. Он вставляет её в программу Hudini Host на своём ПК, и пульт находит его сам.": "Klick im Menü „Mehr“ auf „Kopieren“ und schick den Link dem Streamer. Er fügt ihn in Hudini Host auf seinem PC ein, und das Pult findet es selbst.",
    "Всё ли на связи": "Ist alles verbunden",
    "Полоски и миллисекунды: связь с программой стримера и её задержка. Рядом видно, работает ли виджет в OBS. Если что-то не так, нажми на плашку.": "Balken und Millisekunden zeigen die Verbindung zum Programm des Streamers und ihre Verzögerung. Daneben siehst du, ob das Widget in OBS läuft. Wenn etwas nicht stimmt, klick auf die Anzeige.",
    "⋯ Ещё": "⋯ Mehr",
    "Ссылка для стримера, рамка, пароль, очистка": "Streamer-Link, Rahmen, Passwort, Leeren",
    "Метки β и α": "Markierungen β und α",
    "β: работает, но ещё обкатывается. α: эксперимент. Нажми на метку, чтобы узнать больше или сообщить о проблеме.": "β: funktioniert, wird aber noch erprobt. α: ein Experiment. Klick auf eine Markierung, um mehr zu erfahren oder ein Problem zu melden.",
    "Гайд всегда здесь": "Die Anleitung ist immer hier",
    "Кнопка ❓ покажет обучение ещё раз и откроет справку прямо в пульте.": "Der Knopf ❓ zeigt die Tour noch einmal und öffnet die Hilfe direkt im Pult.",
    "🎛 Настроим под тебя": "🎛 Richten wir es für dich ein",
    "Выбери, как пульт будет выглядеть. Всё это можно поменять потом: Комната → Вид пульта.": "Wähle, wie das Pult aussehen soll. Du kannst alles später ändern: Raum → Aussehen des Pults.",
    "Поехали": "Los geht's",
