    "Добавь текст или картинку слева,": "Füge links Text oder ein Bild hinzu,",
    "или просто перетащи файл сюда": "oder zieh einfach eine Datei hierher",
    "📁 Место для файлов модераторов": "📁 Platz für Dateien der Mods",
    "Модераторы загружают картинки, GIF и видео. Они хранятся на этом компьютере в папке программы, зашифрованными. Сколько места им дать?": "Mods laden Bilder, GIFs und Videos hoch. Sie liegen verschlüsselt auf diesem Computer im Ordner des Programms. Wie viel Platz sollen sie bekommen?",
