    "Свой адрес для модераторов.": "Eigene Adresse für Mods.",
    "Вместо бесплатного туннеля Cloudflare: Tailscale Funnel, свой туннель Cloudflare или свой домен. Направь его на": "Statt des kostenlosen Cloudflare-Tunnels: Tailscale Funnel, ein eigener Cloudflare-Tunnel oder eine eigene Domain. Leite sie auf",
    "и впиши адрес вида": "und trage eine Adresse ein wie",
    ". Пусто = обычный туннель.": ". Leer = normaler Tunnel.",
    "Свой адрес сохранён ✓": "Eigene Adresse gespeichert ✓",
    "Вернул обычный туннель ✓": "Zurück zum normalen Tunnel ✓",
    "Адрес и пароль для пульта.": "Adresse und Passwort für das Pult.",
    "Обычно пульт находит программу сам. Если нет, модератор вписывает их в пульте: «Комната» → «Для продвинутых». Никому больше не показывай.": "Normalerweise findet das Pult das Programm selbst. Falls nicht, trägt der Mod sie im Pult ein: „Raum“ → „Für Fortgeschrittene“. Zeig sie niemandem sonst.",
    "адрес появится, когда заработает туннель": "die Adresse erscheint, sobald der Tunnel läuft",
    "Новый пароль модераторов.": "Neues Mod-Passwort.",
    "Все модераторы отключатся на пару секунд и подключатся снова сами. Чтобы закрыть доступ человеку насовсем, модератор нажимает в пульте «♻ Сменить ключи», а ты вставляешь новую ссылку в шаг 1.": "Alle Mods werden für ein paar Sekunden getrennt und verbinden sich selbst neu. Um jemandem den Zugang dauerhaft zu entziehen, klickt ein Mod im Pult auf „♻ Schlüssel ändern“, und du fügst den neuen Link in Schritt 1 ein.",
    "🔑 Новый пароль": "🔑 Neues Passwort",
    "Новый пароль ✓": "Neues Passwort ✓",
    "Сменить пароль модераторов? Все модераторы отключатся на минуту.": "Mod-Passwort ändern? Alle Mods werden kurz getrennt.",
    "Файлы": "Dateien",
