    "нет связи (пульт попробует последний адрес)": "keine Verbindung (das Pult versucht die letzte Adresse)",
    "Попроси модератора нажать в пульте «📋 Копировать» и вставь эту ссылку сюда. Нужно сделать один раз, программа её запомнит.": "Bitte deinen Mod, im Pult auf „📋 Kopieren“ zu klicken, und füge den Link hier ein. Das musst du nur einmal machen, das Programm merkt ihn sich.",
